SELECT COUNT(*)
FROM system_parameter
WHERE tenant_id = #{tenantId} AND parameter_key = #{parameterKey}

SELECT COUNT(*)
FROM system_number_rule
WHERE tenant_id = #{tenantId} AND rule_code = #{ruleCode}

SELECT current_value
FROM system_number_sequence
WHERE tenant_id = #{tenantId}
  AND rule_id = #{ruleId}
  AND period_key = #{periodKey}
